(()=>{
'use strict';const $=s=>document.querySelector(s),core=window.CompositionLesson,num=window.LinearLesson;
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}
const symbols={add:'+',subtract:'-',multiply:'\\times',divide:'\\div'};
function operation(){const x=Number($('#operation-input').value),kind=$('[name="operation"]:checked').value,a=core.f(x),b=core.g(x),result=core.operation(kind,x);$('#operation-output').value=x;math($('#f-value'),`f(${x})=${a}`);math($('#g-value'),`g(${x})=${b}`);let tex;if(kind==='divide')tex=result===null?`\\frac{${a}}{${b}}\\quad\\text{tidak terdefinisi}`:`\\frac{${a}}{${b}}=${num.fractionTex(num.rational(a,b))}`;else tex=`(${a})${symbols[kind]}(${b})=${result}`;math($('#operation-equation'),tex);$('#operation-feedback').textContent=result===null?'Pembagian tidak dapat dilakukan pada masukan nol karena keluaran fungsi penyebut nol. Operasi ini tidak menghasilkan bilangan real.':kind==='divide'?'Kedua fungsi memakai masukan awal yang sama. Keluaran fungsi pertama dibagi keluaran fungsi kedua, yang bukan nol.':'Kedua fungsi memakai masukan awal yang sama, kemudian kedua keluarannya dioperasikan. Ini berbeda dari komposisi.';math($('#operation-domain'),kind==='divide'?'D=(-\\infty,0)\\cup(0,\\infty)':'D=\\mathbb R');}
$('#operation-input').addEventListener('input',operation);document.querySelectorAll('[name="operation"]').forEach(e=>e.addEventListener('change',operation));operation();
function compose(){const order=$('[name="composition"]:checked').value,x=Number($('#composition-input').value),c=core.compose(order,x),fg=order==='fg';$('#composition-output').value=x;math($('#stage-input'),String(x));math($('#stage-middle'),`${fg?'g':'f'}(${x})=${c.middle}`);math($('#stage-final'),`${fg?'f':'g'}(${c.middle})=${c.result}`);$('#first-stage-label').textContent=fg?'Tahap 1 · fungsi kuadrat':'Tahap 1 · fungsi linear';$('#second-stage-label').textContent=fg?'Tahap 2 · fungsi linear':'Tahap 2 · fungsi kuadrat';math($('#composition-equation'),fg?`(f\\circ g)(${x})=f(g(${x}))=f(${c.middle})=${c.result}`:`(g\\circ f)(${x})=g(f(${x}))=g(${c.middle})=${c.result}`);$('#composition-feedback').innerHTML=`Jika urutan dibalik, hasilnya <span data-tex="${c.other}"></span>. `+(c.result===c.other?'Pada masukan ini hasilnya kebetulan sama. Coba masukan lain sebelum menyimpulkan kedua fungsi komposisi sama.':'Hasilnya berbeda. Perhatikan keluaran tahap pertama yang menjadi masukan tahap kedua.');}
$('#composition-input').addEventListener('input',compose);document.querySelectorAll('[name="composition"]').forEach(e=>e.addEventListener('change',compose));$('#reset-composition').addEventListener('click',()=>{$('[name="composition"][value="fg"]').checked=true;$('#composition-input').value=2;compose();});compose();
const questions=[{tex:'(f+g)(3)',n:16,hint:'Hitung kedua keluaran pada masukan tiga, lalu jumlahkan.',why:'Keluaran fungsi pertama tujuh dan keluaran fungsi kedua sembilan; jumlahnya enam belas.'},{tex:'(fg)(3)',n:63,hint:'Gunakan masukan tiga untuk kedua fungsi, kemudian kalikan keluarannya.',why:'Tujuh dikali sembilan menghasilkan enam puluh tiga. Dua fungsi tetap menerima masukan awal yang sama.'},{tex:'(f\\circ g)(2)',n:9,hint:'Kerjakan fungsi kuadrat dahulu, lalu masukkan hasilnya ke fungsi linear.',why:'Dua dikuadratkan menjadi empat. Fungsi linear kemudian menghasilkan dua kali empat ditambah satu, yaitu sembilan.'},{tex:'(g\\circ f)(2)',n:25,hint:'Kerjakan fungsi linear dahulu, kemudian kuadratkan seluruh keluarannya.',why:'Fungsi linear menghasilkan lima. Setelah dikuadratkan, hasil akhirnya dua puluh lima.'}];const solved=new Set();function report(i,ok,message){const e=$('#feedback'+i);e.className='feedback '+(ok?'correct':'incorrect');e.textContent=message;if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari 6 latihan sudah dijawab tepat.`;}
$('#questions').innerHTML=questions.map((q,i)=>`<div class="question"><h3 data-no-equation>Latihan ${i+1}</h3><p>Tentukan nilai <span data-tex="${q.tex}"></span>.</p><form data-question="${i}"><label for="answer${i}">Jawabanmu</label><div class="answer-line"><input id="answer${i}" type="text" required autocomplete="off" aria-describedby="feedback${i}"><button class="button" type="submit">Periksa jawaban</button></div></form><p id="feedback${i}" class="feedback" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.hint}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('form[data-question]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const i=Number(form.dataset.question),q=questions[i],a=num.parseAnswer($('#answer'+i).value),ok=num.equalAnswer(a,num.rational(q.n));report(i,ok,ok?'Tepat. '+q.why:!a?'Tulis satu bilangan, misalnya 9.':'Belum tepat. Periksa simbol operasi dan fungsi yang dikerjakan lebih dahulu.');}));
const choices=[{tex:'f(x)=2x+1,\\quad g(x)=x^2',prompt:'Apa domain fungsi hasil bagi fungsi pertama oleh fungsi kedua?',options:['Semua bilangan real.','Semua bilangan real selain nol.','Hanya bilangan real positif.'],answer:1,why:'Kedua rumus menerima semua masukan real, tetapi fungsi penyebut menghasilkan nol pada masukan nol. Masukan negatif selain nol tetap boleh.'},{tex:'u(t)=\\sqrt t,\\quad v(x)=2x-1',prompt:'Dengan domain real terbesar masing-masing fungsi, apa domain u komposisi v?',options:['Lebih besar dari atau sama dengan nol.','Lebih besar dari setengah, tanpa setengah.','Lebih besar dari atau sama dengan setengah.'],answer:2,why:'Keluaran fungsi linear harus tidak negatif agar dapat masuk ke akar kuadrat. Dua kali masukan dikurangi satu harus tidak negatif. Batas setengah ikut karena akar nol terdefinisi.'}];for(let j=0;j<choices.length;j++){const i=j+4,q=choices[j],box=document.createElement('div');box.className='question';box.innerHTML=`<h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><fieldset><legend>${q.prompt}</legend>${q.options.map((o,k)=>`<label class="choice"><input type="radio" name="choice${i}" value="${k}">${o}</label>`).join('')}</fieldset><button type="button" class="button" data-check="${i}">Periksa jawaban</button><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details>`;$('#questions').append(box);box.querySelector('button').addEventListener('click',()=>{const a=$(`[name="choice${i}"]:checked`),ok=!!a&&Number(a.value)===q.answer;report(i,ok,!a?'Pilih jawaban dahulu.':(ok?'Tepat. ':'Belum tepat. ')+q.why);});}
const storage={get(k){try{return localStorage.getItem('fondasi-composition-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-composition-'+k,v);return true}catch{return false}}};$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#save-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan di peramban ini.':'Catatan belum dapat disimpan; salin jika diperlukan.';});function complete(saved){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#complete-note').textContent=saved?'Kemajuan tersimpan di peramban ini. Kamu bisa mencoba kembali kapan saja.':'Bacaan selesai; kemajuan belum dapat disimpan di peramban ini.';}$('#complete').addEventListener('click',()=>complete(storage.set('complete','yes')));if(storage.get('complete')==='yes')complete(true);
})();